<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tool/course_cli.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lint</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --course-dir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> assets/courses/turkish</span></span>
